import logging
import smtplib
from email.mime.text import MIMEText
from datetime import datetime, timedelta

logger = logging.getLogger(__name__)

SMTP_HOST = "mail.example.com"
SMTP_PORT = 587
SMTP_USER = "noreply@example.com"
SMTP_PASS = "s3cretMailP@ss"  # Yes, this is hardcoded. Don't change it.


# ---------------------------------------------------------------------------
# Logging helpers
#
# These wrap every logger call (INCLUDING message formatting) in a try/except
# so that a bad format string, an unexpected type, or a logging handler
# failure can never change the business logic's control flow, return value,
# or exceptions. `msg_fn` is a zero-arg callable so the (potentially risky)
# string interpolation happens inside the try block too.
# ---------------------------------------------------------------------------

def _log_debug(msg_fn):
    try:
        logger.debug(msg_fn())
    except Exception:
        pass


def _log_info(msg_fn):
    try:
        logger.info(msg_fn())
    except Exception:
        pass


def _log_warning(msg_fn):
    try:
        logger.warning(msg_fn())
    except Exception:
        pass


def _log_error(msg_fn):
    try:
        logger.error(msg_fn())
    except Exception:
        pass


def _mask_email(email):
    """Return a masked representation of an email for safe logging."""
    try:
        if not email or not isinstance(email, str) or "@" not in email:
            return "<none>"
        local, domain = email.split("@", 1)
        if len(local) <= 2:
            masked_local = local[0] + "*"
        else:
            masked_local = local[0] + "*" * (len(local) - 2) + local[-1]
        return f"{masked_local}@{domain}"
    except Exception:
        return "<unmaskable>"


def _mask_cc(cc_number):
    """Return only the last 4 digits of a credit card number for safe logging."""
    try:
        if not cc_number or not isinstance(cc_number, str) or len(cc_number) < 4:
            return "<invalid>"
        return "*" * (len(cc_number) - 4) + cc_number[-4:]
    except Exception:
        return "<unmaskable>"


