    _log_debug(lambda: f"_charge_card: entered cc_number={_mask_cc(cc_number)} amount={amount}")
    # Simulate credit card charge
    if amount <= 0:
        _log_error(lambda: f"_charge_card: invalid amount={amount}")
        return {"success": False, "error": "Invalid amount"}
    result = {"success": True, "transaction_id": f"txn_{datetime.now().timestamp()}"}
    _log_info(lambda: f"_charge_card: succeeded transaction_id={result['transaction_id']!r}")
    return result


def _charge_paypal(email, amount):
    _log_debug(lambda: f"_charge_paypal: entered email={_mask_email(email)} amount={amount}")
    # Simulate PayPal charge
    if not email:
        _log_error(lambda: "_charge_paypal: no email provided")
        return {"success": False, "error": "No email for PayPal"}
    result = {"success": True, "transaction_id": f"pp_{datetime.now().timestamp()}"}
    _log_info(lambda: f"_charge_paypal: succeeded transaction_id={result['transaction_id']!r}")
    return result


def _send_email(to_addr, subject, body):
    _log_debug(lambda: f"_send_email: entered to={_mask_email(to_addr)} subject={subject!r}")
    msg = MIMEText(body)
    msg["Subject"] = subject
    msg["From"] = SMTP_USER
    msg["To"] = to_addr
    try:
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT) as server:
            server.starttls()
            server.login(SMTP_USER, SMTP_PASS)  # SMTP_PASS is never logged
            server.send_message(msg)
        _log_info(lambda: f"_send_email: succeeded to={_mask_email(to_addr)}")
    except Exception as e:
        _log_error(lambda: f"_send_email: failed to={_mask_email(to_addr)} error={e!r}")
        raise
